import heapq
import random


class Node:
    __slots__ = ('val', 'ch', 'sib')

    def __init__(self, val):
        self.val = val
        self.ch = None
        self.sib = None


def meld(a, b):
    """合并两个配对堆，返回新根。O(1) 均摊"""
    if a is None:
        return b
    if b is None:
        return a
    if a.val > b.val:
        a, b = b, a
    b.sib = a.ch
    a.ch = b
    return a


def insert(root, val):
    return meld(root, Node(val))


def _pairs(first):
    """两两配对合并儿子链，再自右向左合并（删除最小值核心）"""
    if first is None or first.sib is None:
        return first
    a, b = first, first.sib
    rest = b.sib
    a.sib = b.sib = None
    return meld(_pairs(rest), meld(a, b))


def pop_min(root):
    """删除最小值。返回 (新根, 原最小值)；空堆返回 (None, None)"""
    if root is None:
        return None, None
    return _pairs(root.ch), root.val


def decrease_key(root, node, new_val):
    """把 node 的值减小为 new_val（须保证 new_val <= node.val）"""
    if new_val > node.val:
        raise ValueError('decrease_key 只能减小')
    node.val = new_val
    # 若 node 是根则直接返回
    # 本实现为无父指针的简化版：此处仅演示；完整实现需 fa 指针把 node 从父链剖出后 meld(root, node)
    return root


if __name__ == '__main__':
    random.seed(2)
    h = None
    ref = []
    for _ in range(5000):
        op = random.random()
        if op < 0.5 or not ref:
            v = random.randint(0, 100000)
            h = insert(h, v)
            heapq.heappush(ref, v)
        else:
            h, m = pop_min(h)
            r = heapq.heappop(ref)
            assert m == r, (m, r)
        if h is None:
            assert not ref
    # 双堆合并验证
    h1 = h2 = None
    r1, r2 = [], []
    for v in [9, 3, 7, 1, 5]:
        h1 = insert(h1, v); r1.append(v)
    for v in [8, 2, 6, 0, 4]:
        h2 = insert(h2, v); r2.append(v)
    h = meld(h1, h2)
    r = sorted(r1 + r2)
    out = []
    while h is not None:
        h, m = pop_min(h)
        out.append(m)
    assert out == r, (out, r)
    print('pairing heap: All tests passed.')
